class Solution:
    def findLeaves(self, root) -> list[list[int]]:
        result = []
        def dfs(node):
            if not node:
                return -1
            h = max(dfs(node.left), dfs(node.right)) + 1
            if h == len(result):
                result.append([])
            result[h].append(node.val)
            return h
        dfs(root)
        return result

